using System.Net;
using System.Net.Http;
using Dedsec.Tests;
internal static class UpdateChecks
{
    internal static async Task Live(Action<bool,string> check)
    {
        using var client=UpdateNetwork.Create();using var source=System.Text.Json.JsonDocument.Parse(await UpdateNetwork.Metadata(client,"https://api.github.com/repos/Dedseckms/Dedsec-Tests/releases?per_page=20",2_000_000,CancellationToken.None));var release=Updates.Select(source.RootElement,Updates.Architecture,new Version(0,2,0))??throw new Exception("No actual compatible release");
        var metadata=await UpdateNetwork.Metadata(client,release.ManifestUrl,16384,CancellationToken.None);var signature=await UpdateNetwork.Metadata(client,release.SignatureUrl,512,CancellationToken.None);var manifest=Dedsec.Update.Trust.Verify(metadata,signature);check(manifest.Version==release.Version.ToString(3),"Live .NET transport reads GitHub API and redirected signed metadata with normal TLS validation");
        string directory=Path.Combine(Path.GetTempPath(),"DedsecLiveUpdate-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);string file=Path.Combine(directory,"package.zip");using var deadline=new CancellationTokenSource(TimeSpan.FromMinutes(5));await UpdateNetwork.Download(client,manifest.Url,file,manifest.Size,new ConsoleProgress(),deadline.Token);Dedsec.Update.Trust.VerifyPackage(file,manifest);check(true,"Actual GitHub release package downloads completely and matches signed SHA256 and size; no installation performed");
    }
    internal static async Task Run(Action<bool,string> check)
    {
        string area=Path.Combine(Path.GetTempPath(),"DedsecNetwork-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(area);
        var handler=new Handler((number,_)=>number==1?throw new HttpRequestException("connection reset"):Response(new byte[]{1,2,3},3));using(var client=new HttpClient(handler)){var data=await UpdateNetwork.Metadata(client,"https://example.invalid/test",10,CancellationToken.None);check(handler.Calls==2&&data.SequenceEqual(new byte[]{1,2,3}),"Update metadata retries a failed connection and returns measured bytes");}
        byte[] expected=Enumerable.Range(0,180000).Select(i=>(byte)i).ToArray();var bodyRetry=new Handler((n,_)=>Response(n==1?expected[..100]:expected,expected.Length));var progress=new CaptureProgress<PackageProgress>();string package=Path.Combine(area,"package.zip");
        using(var client=new HttpClient(bodyRetry)){await UpdateNetwork.Download(client,"https://example.invalid/file",package,expected.Length,progress,CancellationToken.None);check(bodyRetry.Calls==2&&File.ReadAllBytes(package).SequenceEqual(expected)&&progress.Values.Last().Received==expected.Length&&progress.Values.Last().Attempt==2,"Interrupted package starts afresh, reports real bytes and never appends corrupt partial data");}
        var large=new Handler((_,_)=>Response(new byte[11],10));using(var client=new HttpClient(large)){try{await UpdateNetwork.Download(client,"https://example.invalid/large",package,10,new CaptureProgress<PackageProgress>(),CancellationToken.None);throw new Exception("Oversize accepted");}catch(InvalidDataException){check(large.Calls==1,"Oversized update is refused without automatic retry");}}
        var pending=new Handler((_,_)=>new HttpResponseMessage(HttpStatusCode.OK){Content=new StreamContent(new PendingStream())});using(var client=new HttpClient(pending))using(var cancel=new CancellationTokenSource(100)){try{await UpdateNetwork.Download(client,"https://example.invalid/slow",package,10,new CaptureProgress<PackageProgress>(),cancel.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){using var writable=File.Open(package,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);check(pending.Calls==1,"Cancel interrupts a blocked read and releases the partial download file");}}
        var tls=new HttpRequestException(HttpRequestError.SecureConnectionError,"SSL connection failed",new System.Security.Authentication.AuthenticationException("Certificate chain is untrusted"));check(UpdateNetwork.Explain(tls).Contains("защищённое")&&UpdateNetwork.Details(tls).Contains("Certificate chain is untrusted"),"TLS explanation keeps the actual inner certificate error and offers manual download");
        string json="""[{"draft":false,"tag_name":"v0.3.1","body":"preview","assets":[{"name":"update-x64.json","browser_download_url":"https://github.com/Dedseckms/Dedsec-Tests/releases/download/v0.3.1/update-x64.json"},{"name":"update-x64.sig","browser_download_url":"https://github.com/Dedseckms/Dedsec-Tests/releases/download/v0.3.1/update-x64.sig"}]},{"draft":true,"tag_name":"v99.0.0","assets":[]}]""";using var releases=System.Text.Json.JsonDocument.Parse(json);check(Updates.Select(releases.RootElement,"x64",new Version(0,2,0))?.Version==new Version(0,3,1)&&Updates.Select(releases.RootElement,"x86",new Version(0,2,0))==null&&Updates.Select(releases.RootElement,"x64",new Version(0,3,1))==null,"Discovery selects a newer compatible signed preview, ignores drafts and never downgrades");
    }
    private static HttpResponseMessage Response(byte[] data,long declared){var content=new ByteArrayContent(data);content.Headers.ContentLength=declared;return new(HttpStatusCode.OK){Content=content};}
    private sealed class Handler(Func<int,HttpRequestMessage,HttpResponseMessage> action):HttpMessageHandler{internal int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken)=>Task.FromResult(action(++Calls,request));}
    private sealed class CaptureProgress<T>:IProgress<T>{internal readonly List<T> Values=new();public void Report(T value)=>Values.Add(value);}
    private sealed class ConsoleProgress:IProgress<PackageProgress>{private DateTime last;public void Report(PackageProgress value){if((DateTime.UtcNow-last).TotalSeconds<5&&value.Received!=value.Total)return;last=DateTime.UtcNow;Console.WriteLine($"DOWNLOAD attempt={value.Attempt} received={value.Received} / {value.Total} speed={value.BytesPerSecond:F0} B/s");}}
    private sealed class PendingStream:Stream
    {
        public override bool CanRead=>true;public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>throw new NotSupportedException();public override long Position{get=>throw new NotSupportedException();set=>throw new NotSupportedException();}public override void Flush(){}public override int Read(byte[] buffer,int offset,int count)=>throw new NotSupportedException();public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();public override void Write(byte[] buffer,int offset,int count)=>throw new NotSupportedException();public override async ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken cancellationToken=default){await Task.Delay(Timeout.Infinite,cancellationToken);return 0;}
    }
}
